import { existsSync, readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

/**
 * package.json is regenerated by Speakeasy, which owns its exports map. The
 * hand-written subpaths are reached through the generated "./*" pattern,
 * which maps them to the barrel files in src/extra/ and src/hooks/. This
 * fails if a regeneration stops exporting one of them, which nothing else
 * would notice since the tests import from src/.
 */
const packageRoot = new URL("../", import.meta.url);
const packageJson = JSON.parse(
  readFileSync(new URL("package.json", packageRoot), "utf-8"),
);

type ExportEntry = { source: string; types: string; default: string };

/** Resolves a subpath against the exports map the way Node does. */
function resolveExport(subpath: string): ExportEntry | undefined {
  const exports: Record<string, ExportEntry> = packageJson.exports;
  if (exports[subpath]) {
    return exports[subpath];
  }

  // Of the matching patterns, the one with the longest prefix wins.
  const pattern = Object.keys(exports)
    .filter((key) => {
      const [prefix, suffix] = key.split("*");
      return suffix !== undefined
        && subpath.startsWith(prefix!)
        && subpath.endsWith(suffix)
        && subpath.length >= key.length - 1;
    })
    .sort((a, b) => b.indexOf("*") - a.indexOf("*"))[0];
  if (pattern === undefined) {
    return undefined;
  }

  const [prefix, suffix] = pattern.split("*");
  const star = subpath.slice(prefix!.length, subpath.length - suffix!.length);
  const entry = exports[pattern]!;
  return {
    source: entry.source.replace("*", star),
    types: entry.types.replace("*", star),
    default: entry.default.replace("*", star),
  };
}

const HAND_WRITTEN_EXPORTS = [
  "./extra/realtime",
  "./extra/observability",
  "./extra/connectors",
  "./extra/workflows",
  "./extra/voice-agents",
  "./extra/voice-agents/browser",
  "./extra/voice-agents/audio/node",
  "./hooks/tracing",
];

describe("package.json exports", () => {
  it.each(HAND_WRITTEN_EXPORTS)("exports %s from an existing source", (path) => {
    const entry = resolveExport(path);

    expect(entry).toBeDefined();
    expect(existsSync(new URL(entry!.source, packageRoot))).toBe(true);
  });
});
